ST.xhtml:
//*****************************************************//
//*********************STATUS INIT*********************//
//*****************************************************//
IF status = en_commStatus.INIT THEN
	//clear last know gps localisations list
	GVL.GPS_Last_Positions_Index:=0;
	GVL.GPSHeadingFilterDataIndex:=0;
	GVL.TargetReached:=TRUE;
	GVL.GPSFix:=0;
	GVL.TargetLongitude:=0;
 	GVL.TargetLatitude:=0;

	GVL.DeviceConnected:=FALSE; //no device is connected

	//If for some reasons, we are still in manual mode, exit:  
	GVL.manualControl.setManualModeInactive(); //GVL.ManualControlState:=0;

	GVL.ManualControlDemand:=FALSE; 
	GVL.ComCart1Rot:=FALSE;
	GVL.ComCart2Rot:=FALSE;
	GVL.ComCart1RotDir:=FALSE;
	GVL.ComCart2RotDir:=FALSE;
	GVL.ComCartsStraight:=FALSE;
	GVL.ComCart1RotDir:=FALSE;
	GVL.RPMUserRequest:=255; //engine is free


// Initialization part
	IF can_inited = FALSE THEN   			
		//init a can channel
		io_error := lib500.IO_CAN_Init(GVL.CAN_BT_CHANNEL,
							lib500_types.IO_CAN_BAUDRATE.IO_CAN_BIT_250_KB,
							0,
							0,
							0,
							0);
		IF 	(io_error=lib500_types.IO_ERRORTYPE.IO_E_OK OR io_error=lib500_types.IO_ERRORTYPE.IO_E_CHANNEL_BUSY) THEN //check if can channel is ready
			can_inited := TRUE;  //set that the can channel has been inited
		END_IF
	ELSE //if can channel has been inited properly
			//init the rx FIFO buffer
			IF GVL.BT_RXCanFramesFIFO.bReady=FALSE THEN
				io_error := GVL.BT_RXCanFramesFIFO.Create(GVL.CAN_BT_CHANNEL, 
															BT_CAN_ID_FORMAT,
															16#70,	
															16#0000);
			ELSE //if RX fifo is ready, create writing message object
				io_error:=lib500.IO_CAN_ConfigMsg(ADR(hWriteMsg),
												GVL.CAN_BT_CHANNEL,
												liB500_types.IO_CAN_MODE.IO_CAN_MSG_WRITE,
												BT_CAN_ID_FORMAT,
												0,
												0);
				IF (io_error=lib500_types.IO_ERRORTYPE.IO_E_OK) THEN //if writing msg object is ready, the can is working and we should be able to talk
					status := en_commStatus.WAITING_FOR_HS;
				END_IF
			END_IF									
	END_IF

//*****************************************************//
//***********STATUS WAITING FOR HAND SHAKE*************//
//*****************************************************//
ELSIF status = en_commStatus.WAITING_FOR_HS THEN
	//If there was connection loss, then exit manual mode:
	GVL.manualControl.setManualModeInactive();			//GVL.ManualControlState :=0;
	//read fifo till the end
	WHILE GVL.BT_RXCanFramesFIFO.uiAvailableFrames<>0 DO
		RX_Frame:=GVL.BT_RXCanFramesFIFO.getFirstFrame();
		IF RX_Frame.udiCanID=0 THEN //something went wrong! need to deinit and back to status 0
			//deinit routine
			//.
			//.
			//.
			/////////
			status:=en_commStatus.INIT;
		ELSE //check what we got
			IF RX_Frame.udiCanID = en_canFrameID.CAN_ID_RXHandShake THEN //if the message is a handshake initalization

				//construct response frame to send
				TX_Frame.id:=en_canFrameID.CAN_ID_TXHandShake;
				TX_Frame.id_format:=BT_CAN_ID_FORMAT;
				TX_Frame.length:=1;
				TX_Frame.data[0]:=1; //set the data for handshake //agribot ID
				//send confirmation with agribots ID
				lib500.IO_CAN_WriteMsg(hWriteMsg,
										ADR(TX_Frame)); //answer on handshake, send agribots ID
				TXTimeoutTimer(IN:=TRUE, PT:=TXTimeout);
				WHILE (lib500.IO_CAN_MsgStatus(hWriteMsg) <> lib500_types.IO_ERRORTYPE.IO_E_OK) DO
					IF TXTimeoutTimer.Q=TRUE THEN
						EXIT;
					END_IF
				END_WHILE
				IF TXTimeoutTimer.Q=FALSE THEN //if timeout was not reached
					GVL.DeviceConnected:=TRUE; //device connected flag set

					RXHeartbeatTimer(IN:=FALSE, PT:=RXHeartbeatTimerPeriod); //start heartbeat checking
					RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); //start heartbeat checking
					hearbeat_counter:=255;  								//set heartbeat on 1 before 0

					RXManualControlTimer(IN:=FALSE, PT:=RXManualControlTimerPeriod);
					RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);

					status:=en_commStatus.RUNNING;	// the connection is established
					EXIT; //break the buffer reading
				END_IF	
				//reset timeout timer		
				TXTimeoutTimer.IN:=FALSE;

			END_IF
			//if not, keep looking in the remaining data frames		
		END_IF
	END_WHILE
//***********************************************************//
//**************STATUS RUNNING OR MANUAL********************//
//*********************************************************//	
ELSIF status=en_commStatus.RUNNING OR status=en_commStatus.MANUAL THEN
		//!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
		//BEGIN WITH HEARTBEAT CHECKING
		//!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
			IF RXHeartbeatTimer.Q THEN //if heartbeat was absent for 200ms, then disconnect
				status := en_commStatus.WAITING_FOR_HS;//back to waiting state
				GVL.DeviceConnected:=FALSE; //no connection flag

				//If heartbeat was lost, exit manual mode:  
				GVL.manualControl.setManualModeInactive(); //GVL.ManualControlState:=0;

				//turn off the manual commands
				GVL.ComCart1Rot:=FALSE;
				GVL.ComCart2Rot:=FALSE;
				GVL.ComCartsStraight:=FALSE;
				GVL.ComCartFrontStraight:=FALSE;
				GVL.ComCartBackStraight:=FALSE;
				GVL.Manual_Arc_Continue:=FALSE;
				GVL.Manual_Arc_Radius:=0;
				GVL.ManualStartEngineRequest:=FALSE;
				GVL.RPMUserRequest:=255; //engine is free

				GVL.TargetReached:=TRUE;

				//turn off switches
				Switch_iterator:=1;
				WHILE Switch_iterator<=12 DO
					GVL.SwitchState[Switch_iterator]:=FALSE;
					GVL.SwitchSetLevel[Switch_iterator]:=0;
					Switch_iterator:=Switch_iterator+1;
				END_WHILE
				//send error message, connection lost, reason: lack of heartbeat, connection is unstable 

				//construct the error frame to send
				TX_Frame.id := en_canFrameID.CAN_ID_TXError;
				TX_Frame.id_format:=BT_CAN_ID_FORMAT;
				TX_Frame.length:=2;
				TX_Frame.data[0]:=16#00;
				TX_Frame.data[1]:=16#0F;
				lib500.IO_CAN_WriteMsg(hWriteMsg,
										ADR(TX_Frame)); 
				TXTimeoutTimer(IN:=TRUE, PT:=TXTimeout);
				WHILE (lib500.IO_CAN_MsgStatus(hWriteMsg) <> lib500_types.IO_ERRORTYPE.IO_E_OK) DO
					IF TXTimeoutTimer.Q=TRUE THEN
						EXIT;
					END_IF
				END_WHILE
				//reset timeout timer		
				TXTimeoutTimer.IN:=FALSE;
			ELSE 		//if heartbeat is healthy, then go on with routine
				RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); //keep on the heartbeat timer
		END_IF		
		//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
		//if in manual mode, check if the button timeout had occured		
		//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
		IF status=en_commStatus.MANUAL THEN
			IF RXManualControlTimer.Q THEN
				GVL.ComCart1Rot:=FALSE;
				GVL.ComCart2Rot:=FALSE;
				GVL.ComCartsStraight:=FALSE;
				GVL.ComCartFrontStraight:=FALSE;
				GVL.ComCartBackStraight:=FALSE;
				GVL.Manual_Arc_Radius:=0;
			ELSE
				RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);
			END_IF

			IF NOT RXStopTimer.Q THEN
				 RXStopTimer(IN:=TRUE, PT:=T#1000MS);
			END_IF		
		END_IF
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//search the buffer for recognizable CAN ID's
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

		WHILE GVL.BT_RXCanFramesFIFO.uiAvailableFrames <> 0 DO //if there is something in the buffer, check what, till the end
		//=======================================================================================================
		//get the next frame from FIFO
			RX_Frame:=GVL.BT_RXCanFramesFIFO.getFirstFrame();
					//=======================================================================================================
		//if received a hearbeat, then reset the timer, if wrong number send error
			IF RX_Frame.udiCanID=en_canFrameID.CAN_ID_Heartbeat THEN
				IF hearbeat_counter=255 THEN
					IF RX_Frame.barrData[0]=0 THEN		//if the last hearbeat has been on the egde (255-0)
						hearbeat_counter:=RX_Frame.barrData[0];    	//save the latest hearbeat
						RXHeartbeatTimer(IN:=FALSE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer
						RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer

						//send your own hearbeat	
						//construct the response frame
						TX_Frame.id:=en_canFrameID.CAN_ID_Heartbeat;
						TX_Frame.id_format:=BT_CAN_ID_FORMAT;
						TX_Frame.length:=1;
						TX_Frame.data[0]:=hearbeat_counter;  		//latest hearbeat
						TX_Frame.data[1]:=16#0F;
						lib500.IO_CAN_WriteMsg(hWriteMsg,
										ADR(TX_Frame)); 
						TXTimeoutTimer(IN:=TRUE, PT:=TXTimeout);
						WHILE (lib500.IO_CAN_MsgStatus(hWriteMsg) <> lib500_types.IO_ERRORTYPE.IO_E_OK) DO
							IF TXTimeoutTimer.Q=TRUE THEN
								EXIT;
							END_IF
						END_WHILE
						//reset transmit timeout timer		
						TXTimeoutTimer.IN:=FALSE;

					END_IF
				ELSE
					IF RX_Frame.barrData[0]-hearbeat_counter=1 THEN 	//check if any hearbeat was missed
						hearbeat_counter:=RX_Frame.barrData[0];    	//save the latest hearbeat
						RXHeartbeatTimer(IN:=FALSE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer
						RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer

						//send your own hearbeat	
						//construct the response frame
						TX_Frame.id:=en_canFrameID.CAN_ID_Heartbeat;
						TX_Frame.id_format:=BT_CAN_ID_FORMAT;
						TX_Frame.length:=1;
						TX_Frame.data[0]:=hearbeat_counter;  		//latest hearbeat
						TX_Frame.data[1]:=16#0F;
						lib500.IO_CAN_WriteMsg(hWriteMsg,
										ADR(TX_Frame)); 
						TXTimeoutTimer(IN:=TRUE, PT:=TXTimeout);
						WHILE (lib500.IO_CAN_MsgStatus(hWriteMsg) <> lib500_types.IO_ERRORTYPE.IO_E_OK) DO
							IF TXTimeoutTimer.Q=TRUE THEN
								EXIT;
							END_IF
						END_WHILE
						//reset transmit timeout timer		
						TXTimeoutTimer.IN:=FALSE;
					ELSE 
						//debugHeart:=RX_Frame.barrData[0]-hearbeat_counter;
						//send error message, connection lost, reason: lack of heartbeat, connection is unstable 

						//construct the error frame to send
						TX_Frame.id:=en_canFrameID.CAN_ID_TXError;
						TX_Frame.id_format:=BT_CAN_ID_FORMAT;
						TX_Frame.length:=2;
						TX_Frame.data[0]:=16#00;
						TX_Frame.data[1]:=16#0F;
						lib500.IO_CAN_WriteMsg(hWriteMsg,
												ADR(TX_Frame)); 
						TXTimeoutTimer(IN:=TRUE, PT:=TXTimeout);
						WHILE (lib500.IO_CAN_MsgStatus(hWriteMsg) <> lib500_types.IO_ERRORTYPE.IO_E_OK) DO
							IF TXTimeoutTimer.Q=TRUE THEN
								EXIT;
							END_IF
						END_WHILE
						//reset timeout timer		
						TXTimeoutTimer.IN:=FALSE;	
					END_IF
				END_IF
			END_IF
		END_WHILE
END_IF

(* get the reason for the error callback *) return_code := lib500.DIAG_CDS_GetErrorReason(ADR(diag_state), ADR(watchdog_state), ADR(error));
(* custom handler code can be placed here *)
(* the choices for the reactions are: -> lib500_types.DIAG_REACTION.DIAG_ERR_NOACTION -> lib500_types.DIAG_REACTION.DIAG_ERR_SAFESTATE -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_SSW0 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_SSW1 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_SSW2 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS00 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS01 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS02 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS03 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS04 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS05 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS06 -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_HS07
it's also possible to combine (binary-or) reactions, like: -> lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_SSW0 OR lib500_types.DIAG_REACTION.DIAG_ERR_DISABLE_SSW1 *)
(* pass the error reaction to the DIAG system *) lib500.DIAG_CDS_SetErrorReaction(reaction);
(* increment call count *) call_count := call_count + 1;

(* get the reason for the notification callback *) return_code := lib500.DIAG_CDS_GetNotificationReason(ADR(diag_state), ADR(watchdog_state), ADR(error));
(* custom handler code can be placed here *)
(* increment call count *) call_count := call_count + 1;

//*****************************************************//
//*********************STATUS 0************************//
//*****************************************************//
IF status=0 THEN
	//clear last know gps localisations list
	GVL.GPS_Last_Positions_Index:=0;
	GVL.GPSHeadingFilterDataIndex:=0;
	licznik:=0;
	WHILE licznik<11 DO
		//GVL.GPSHeadingFilterData[licznik].bearing:=0;
		//GVL.GPS_Last_Positions[licznik].LAT:=0;
		//GVL.GPS_Last_Positions[licznik].LON:=0;
		licznik:=licznik+1;
	END_WHILE
	GVL.TargetReached:=TRUE;
	GVL.GPSFix:=0;
	GVL.TargetLongitude:=0;
 	GVL.TargetLatitude:=0;

	GVL.ManualControlState:=0; //no manual control
	GVL.DeviceConnected:=FALSE; //no device is connected
	GVL.ManualControlDemand:=FALSE; 
	GVL.ComCart1Rot:=FALSE;
	GVL.ComCart2Rot:=FALSE;
	GVL.ComCart1RotDir:=FALSE;
	GVL.ComCart2RotDir:=FALSE;
	GVL.ComCartsStraight:=FALSE;
	GVL.ComCart1RotDir:=FALSE;
	RXStopTimer(in:=TRUE, PT:=T#1S);
	GVL.RPMUserRequest:=255; //engine is free
	//CANBusEnable(eChannel:=ifmDevice.CHAN_3, eBaudrate:=ifmDevice.CAN_BAUDRATE.KBAUD_250, xEnable:=TRUE);
	Application_Status_LED(uiChannel:=0, eColour1:=ifmDevice.LED_COLOUR.RED, eColour2:=ifmDevice.LED_COLOUR.GREEN, eFrequency:=ifmDevice.LED_FLASH_FREQ.FRQ_0_Hz, xOn:=TRUE);
	IF NOT (CANBusEnable.eDiagInfo=ifmTypes.DIAG_INFO.STAT_PREPARING) THEN //check if CANbus is working
		status:=1;
		CANwirelessRXblock(udiIDstart:=16#00, udiIDstop:=16#7FF, eChannel:=ifmDevice.CHAN_3, aData=>DATA_RX, aData=>DATA_RX, xExtended:=FALSE, xEnable:=TRUE);
		IF CANwirelessRXblock.xError THEN  //check if RX block is working
			status:=0; //if TX is not working, connection is still impossible
		END_IF
		DATA_TX[0]:=0;
		CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=001, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);
		IF CANwirelessTXblock.xError THEN //check if TX block is working
			status:=0; //if RX is not working, connection is still impossible
		END_IF
		(*
		IF status=0 THEN
			CANBusRecover(eChannel:=ifmDevice.CHAN_3, usiNumberRetry:=5, tInhibitTime:=T#100MS,xExecute:=TRUE); //uruchom restart
			IF CANBusRecover.xError=FALSE THEN 
				IF CANBusRecover.usiRetryCount<=10 AND CANBusRecover.xDone THEN
					CANBusRecover.xExecute:=FALSE; //ustaw na false
				END_IF 
			ELSE
				status:=0; //jesli error to trzeba cos zrobic, jeszcze nie wiem, narazie wracam do prób uruchomienia
			END_IF
		END_IF	
*)	
	ELSE //check if preparing or try to recover the CAN bus
		IF CANBusEnable.xError = TRUE  THEN
			CANBusRecover(eChannel:=ifmDevice.CHAN_3, usiNumberRetry:=10, tInhibitTime:=T#10MS,xExecute:=TRUE); //uruchom restart
			IF CANBusRecover.xError=FALSE THEN 
				IF CANBusRecover.usiRetryCount<=10 AND CANBusRecover.xDone THEN
					CANBusRecover.xExecute:=FALSE; //ustaw na false
				END_IF 
			ELSE
				status:=0; //jesli error to trzeba cos zrobic, jeszcze nie wiem, narazie wracam do prób uruchomienia
			END_IF
		ELSE
			status:=0; //can bus is still preparing
		END_IF	
	END_IF 	
	IF status=0 THEN //is the bus ready? if status is still 0, then red LED
		Application_Status_LED(uiChannel:=0, eColour1:=ifmDevice.LED_COLOUR.RED, eColour2:=ifmDevice.LED_COLOUR.GREEN, eFrequency:=ifmDevice.LED_FLASH_FREQ.FRQ_0_Hz, xOn:=TRUE);
	ELSE //if status=1 change to green
		Application_Status_LED(uiChannel:=0, eColour1:=ifmDevice.LED_COLOUR.RED, eColour2:=ifmDevice.LED_COLOUR.GREEN, eFrequency:=ifmDevice.LED_FLASH_FREQ.FRQ_0_Hz, xOn:=FALSE);	
	END_IF
//*****************************************************//
//*********************STATUS 1************************//
//*****************************************************//
ELSIF status=1 THEN
	GVL.ManualControlState:=0;	
	CANwirelessRXblock(udiIDstart:=16#00, udiIDstop:=16#7FF, eChannel:=ifmDevice.CHAN_3, aData=>DATA_RX, xExtended:=FALSE, xEnable:=TRUE);
	DATA_TX[0]:=0;
	IF CANwirelessRXblock.xError THEN  //check if RX block is working
			status:=0; //if RX is not working, connection is still impossible
	END_IF
	//CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=001, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);
	//CANwirelessTXblock.eDiagInfo;	
	WHILE CANwirelessRXblock.uiAvailable <> 0 DO //if there is something in the buffer, check what	
		licznik:=licznik+1; 
		IF CANwirelessRXblock.udiID = CAN_ID_RXHandShake THEN //if the message is a handshake initalization
			DATA_TX[0]:=1;
																								//agribot ID
			//send confirmation with agribots ID
			CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXHandShake, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE); //answer on handshake, send agribots ID
			status:=2;	// the connection is established
			GVL.DeviceConnected:=TRUE; //device connected flag set

			RXHeartbeatTimer(IN:=FALSE, PT:=RXHeartbeatTimerPeriod); //start heartbeat checking
			RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); //start heartbeat checking
			hearbeat_counter:=255;  								//set heartbeat on 1 before 0

			RXManualControlTimer(IN:=FALSE, PT:=RXManualControlTimerPeriod);
			RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);

			TXDataTimer(IN:=FALSE, PT:=T#100MS); //start sending agribots data
			TXDataTimer(IN:=TRUE, PT:=T#100MS); //start sending agribots data

			EXIT; //break the buffer reading
		ELSE //if not, keep looking in the remaining data
			CANwirelessRXblock(udiIDstart:=16#00, udiIDstop:=16#7FF, eChannel:=ifmDevice.CHAN_3, aData=>DATA_RX, xExtended:=FALSE, xEnable:=TRUE);
		END_IF
	END_WHILE
//***********************************************************//
//*********************STATUS 2 OR 3************************//
//*********************************************************//	
ELSIF status=2 OR status=3 THEN
//!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
//BEGIN WITH HEARTBEAT CHECKING
//!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
	IF RXHeartbeatTimer.Q THEN //if heartbeat was absent for 200ms, then disconnect
		status:=1;			//back to waiting state
		GVL.DeviceConnected:=FALSE; //no connection flag
		GVL.ManualControlState:=0; //no manual control flag
		//turn off the manual commands
		GVL.ComCart1Rot:=FALSE;
		GVL.ComCart2Rot:=FALSE;
		GVL.ComCartsStraight:=FALSE;
		GVL.ComCartFrontStraight:=FALSE;
		GVL.ComCartBackStraight:=FALSE;
		GVL.Manual_Arc_Continue:=FALSE;
		GVL.Manual_Arc_Radius:=0;
		GVL.ManualStartEngineRequest:=FALSE;
		GVL.RPMUserRequest:=255; //engine is free

		GVL.TargetReached:=TRUE;

		//turn off switches
		Switch_iterator:=1;
		WHILE Switch_iterator<=12 DO
			GVL.SwitchState[Switch_iterator]:=FALSE;
			GVL.SwitchSetLevel[Switch_iterator]:=0;
			Switch_iterator:=Switch_iterator+1;
		END_WHILE
		//send error message, connection lost, reason: lack of heartbeat, connection is unstable 
		DATA_TX[0]:=16#00;		
		DATA_TX[1]:=16#0F;
		CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);
	ELSE 		//if heartbeat is healthy, then go on with routine
		RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); //keep on the heartbeat timer

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//if in manual mode, check if the button timeout had occured		
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
IF status=3 THEN
	IF RXManualControlTimer.Q THEN
		GVL.ComCart1Rot:=FALSE;
		GVL.ComCart2Rot:=FALSE;
		GVL.ComCartsStraight:=FALSE;
		GVL.ComCartFrontStraight:=FALSE;
		GVL.ComCartBackStraight:=FALSE;

		GVL.Manual_Arc_Radius:=0;
	ELSE
		RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);
	END_IF

	IF NOT RXStopTimer.Q THEN
		 RXStopTimer(IN:=TRUE, PT:=T#1000MS);
	END_IF

END_IF
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//Check if you need to send something depending on flags and statuses
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++		
		//=======================================================================================================
		//if manual mode is ready and wasnt confirmed, then confirm it	
		IF (GVL.ManualControlState=2) AND ManualNotConfirmed THEN
			ManualNotConfirmed:=FALSE;  
			DATA_TX[0]:=16#FF;  //dummy byte
			CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_ManualOK, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);	//inform that you are ready
		END_IF

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//search the buffer for recognizable CAN ID's
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

		CANwirelessRXblock(udiIDstart:=16#00, udiIDstop:=16#7FF, eChannel:=ifmDevice.CHAN_3, aData=>DATA_RX, xExtended:=FALSE, xEnable:=TRUE);
		ilosc_wiadomosci:=CANwirelessRXblock.uiAvailable;

		WHILE CANwirelessRXblock.uiAvailable <> 0 DO //if there is something in the buffer, check what, till the end
		//=======================================================================================================
		//if in manual control mode, check the move commands ID's 	
			IF CANwirelessRXblock.udiID=CAN_ID_STOP THEN
					GVL.TargetReached:=TRUE;
					GVL.ComCart1Rot:=FALSE;
					GVL.ComCart2Rot:=FALSE;
					GVL.ComCartsStraight:=FALSE;
					GVL.ComCartFrontStraight:=FALSE;
					GVL.ComCartBackStraight:=FALSE;
					GVL.Manual_Arc_Radius:=0;
					GVL.Manual_Arc_Continue:=FALSE;
					gvl.Manual_Align_Command:=FALSE;
					gvl.Manual_Set_Front_Command:=FALSE;
					gvl.Manual_Set_Back_Command:=FALSE;
					GVL.Manual_IS_BUSY:=FALSE;
					GVL.RPMUserRequest:=255;

					//turn off switches
					Switch_iterator:=1;
					WHILE Switch_iterator<=12 DO
						GVL.SwitchState[Switch_iterator]:=FALSE;
						GVL.SwitchSetLevel[Switch_iterator]:=0;
						Switch_iterator:=Switch_iterator+1;
					END_WHILE

				//reset stop timer
				RXStopTimer(in:=FALSE, PT:=T#1000MS);
				RXStopTimer(in:=TRUE, PT:=T#1000MS);
				//do stuff to stop agribot
			END_IF

			IF CANwirelessRXblock.udiID=CAN_ID_CommandSetGPSTarget THEN
					GPSTargetLAT :=  (SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]))/10000000.0;

					GPSTargetLON :=  (SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]))/10000000.0;

					 //if received new point, check if the last one has been reached
					IF GVL.TargetLatitude<>GPSTargetLAT OR GVL.TargetLongitude<>GPSTargetLON THEN
						IF GVL.TargetReached THEN
							GVL.TargetLatitude:=GPSTargetLAT;
							GVL.TargetLongitude:=GPSTargetLON;
							//new target
							//GVL.TargetReached:=FALSE;
						END_IF						
					END_IF 
			END_IF
		//=======================================================================================================
		//if in manual control mode, check the move commands ID's 
			IF status=3 THEN
				//=======================================================================================================
				//move in line command
				IF CANwirelessRXblock.udiID=CAN_ID_CommandMoveStraight THEN
					IF GVL.Manual_IS_BUSY THEN
						DATA_TX[0]:=CAN_ID_CommandMoveStraight;  //send error code BUSY
						DATA_TX[1]:=16#0F;
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
					ELSE
						//set proper setpoints for MainLogic 
						debugManCommands:=DATA_RX[0];
						IF DATA_RX[0]=1 THEN
							GVL.ComCartsStraightDir:=TRUE;
						ELSE
							GVL.ComCartsStraightDir:=FALSE;
						END_IF

						GVL.Manual_Straight_Speed:=DATA_RX[1];
						IF DATA_RX[2]=1 THEN
							GVL.ComCartFrontStraight:=TRUE;
						ELSE 
							GVL.ComCartFrontStraight:=FALSE;
						END_IF

						IF DATA_RX[3]=1 THEN
							GVL.ComCartBackStraight:=TRUE;
						ELSE 
							GVL.ComCartBackStraight:=FALSE;
						END_IF
						IF GVL.ComCartBackStraight=TRUE AND GVL.ComCartFrontStraight=TRUE THEN	
							IF GVL.ComCartsStraight=FALSE THEN //jesli pierwsze klikniecie na straight, to utrzymaj kąty
								GVL.Manual_Set_Angle_Front_SetPoint:=GVL.Front_Cart_Rotation;
								GVL.Manual_Set_Angle_Back_SetPoint:=GVL.Back_Cart_Rotation;
							END_IF
							GVL.ComCartsStraight:=TRUE;
						ELSE 
							GVL.ComCartsStraight:=FALSE;
						END_IF
						DATA_TX[0]:=CAN_ID_CommandMoveStraight;  //agribot ID 
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandMoveStraight, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);
						//set that carts are no longer aligned
						GVL.Manual_Carts_Aligned:=FALSE;
						//reset manual command timeout
						RXManualControlTimer(IN:=FALSE, PT:=RXManualControlTimerPeriod);
						RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);	
					END_IF
					//=======================================================================================================
					//align the carts 
					ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandAlign THEN
						IF GVL.Manual_IS_BUSY THEN
							DATA_TX[0]:=CAN_ID_CommandAlign;  //send error code BUSY
							DATA_TX[1]:=16#0F;
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
						ELSE 	
							//set proper setpoints for MainLogic
							//changing both carts rotation to X degrees
							IF DATA_RX[1] <=90 THEN
								GVL.Manual_Align_Command:=TRUE; //the main logic will set it to false when is done
								IF DATA_RX[0]=1 THEN
									GVL.Manual_Set_Angle_Front_SetPoint:=DATA_RX[1]/2;
									GVL.Manual_Set_Angle_Back_SetPoint:=DATA_RX[1]/2;
								ELSE
									GVL.Manual_Set_Angle_Front_SetPoint:=-DATA_RX[1]/2;
									GVL.Manual_Set_Angle_Back_SetPoint:=-DATA_RX[1]/2;
								END_IF
								DATA_TX[0]:=CAN_ID_CommandAlign;  //agribot ID 
								CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandAlign, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);							
							ELSE
								DATA_TX[0]:=CAN_ID_CommandAlign;  //send error code BUSY
								DATA_TX[1]:=16#03;			//send error angle too high
								CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
							END_IF
						END_IF
					//=======================================================================================================
					//rotate the carts
					ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandRotCarts THEN
						IF GVL.Manual_IS_BUSY THEN
							DATA_TX[0]:=CAN_ID_CommandRotCarts;  //send error code BUSY
							DATA_TX[1]:=16#0F;
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
						ELSE
							//set proper setpoints for MainLogic 	
							IF DATA_RX[0]=1 THEN
								GVL.ComCart1Rot:=TRUE;
							ELSE 
								GVL.ComCart1Rot:=FALSE;
							END_IF

							IF DATA_RX[1]=1 THEN
								GVL.ComCart1RotDir:=TRUE;
							ELSE 
								GVL.ComCart1RotDir:=FALSE;
							END_IF
							IF DATA_RX[2]=1 THEN
								GVL.ComCart2Rot:=TRUE;
							ELSE 
								GVL.ComCart2Rot:=FALSE;
							END_IF
							IF DATA_RX[3]=1 THEN
								GVL.ComCart2RotDir:=TRUE;
							ELSE 
								GVL.ComCart2RotDir:=FALSE;
							END_IF
							//set that carts are no longer aligned
							GVL.Manual_Carts_Aligned:=FALSE;
							DATA_TX[0]:=CAN_ID_CommandRotCarts;  //agribot ID 
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandRotCarts, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);
							//reset manual command timeout
							RXManualControlTimer(IN:=FALSE, PT:=RXManualControlTimerPeriod);
							RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);	
						END_IF
					//=======================================================================================================
					//prepare for the arc				
(*					ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandPrepArc THEN
						IF GVL.Manual_IS_BUSY THEN
							DATA_TX[0]:=CAN_ID_CommandPrepArc;  //send error code BUSY
							DATA_TX[1]:=16#0F;
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
						ELSE 	
						//set proper setpoints for MainLogic
						//changing carts rotation to 0 degrees
							GVL.Manual_Align_Command:=TRUE; //the main logic will set it to false when is done
							DATA_TX[0]:=CAN_ID_CommandPrepArc; 
							GVL.Manual_Arc_Radius:=0;
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandAlign, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);							
						END_IF
*)
				//=======================================================================================================
				//move along the arc
				ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandArc THEN	
						ArcDir:=DATA_RX[1]; //przod tyl
						ArcRadius:=Data_RX[0];
						ArcDC:=Data_RX[2]; //lewo prawo
						ArcReset:=Data_RX[3];
						//CANwirelessRXblock.usiDLC;
						IF GVL.Manual_IS_BUSY THEN
							DATA_TX[0]:=CAN_ID_CommandArc;  //send error code BUSY
							DATA_TX[1]:=16#0F;
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
						//keep moving along the arc 
						ELSIF GVL.Manual_Arc_Radius<>0 THEN	
							IF Data_RX[3]=1 THEN
								GVL.Manual_Arc_Continue:=FALSE; //new ark
							ELSE
								GVL.Manual_Arc_Continue:=TRUE; //continue the ark
							END_IF
							GVL.Manual_Arc_Radius:=DATA_RX[0];
							IF DATA_RX[2]=1 THEN
								GVL.Manual_Arc_Dir:=TRUE;
							ELSE
								GVL.Manual_Arc_Dir:=FALSE;
							END_IF

							IF DATA_RX[1]=1 THEN
								GVL.Manual_Arc_Fr:=TRUE;
							ELSE
								GVL.Manual_Arc_Fr:=FALSE;
							END_IF


							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandArc, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);		
							//reset manual command timeout
							RXManualControlTimer(IN:=FALSE, PT:=RXManualControlTimerPeriod);
							RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);	

						//are carts aligned?
						ELSIF GVL.Manual_Carts_Aligned OR GVL.Manual_Arc_Continue THEN
							//set that carts are no longer aligned
							GVL.Manual_Carts_Aligned:=FALSE;
							//read the arc's radius for the MainLogic and start moving
							IF Data_RX[3]=1 THEN
								GVL.Manual_Arc_Continue:=FALSE; //new ark
							ELSE
								GVL.Manual_Arc_Continue:=TRUE; //continue the ark
							END_IF
							GVL.Manual_Arc_Radius:=DATA_RX[0];
							IF DATA_RX[2]=1 THEN
								GVL.Manual_Arc_Dir:=TRUE;
							ELSE
								GVL.Manual_Arc_Dir:=FALSE;
							END_IF

							IF DATA_RX[1]=1 THEN
								GVL.Manual_Arc_Fr:=TRUE;
							ELSE
								GVL.Manual_Arc_Fr:=FALSE;
							END_IF

							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandArc, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);		
							//reset manual command timeout
							RXManualControlTimer(IN:=FALSE, PT:=RXManualControlTimerPeriod);
							RXManualControlTimer(IN:=TRUE, PT:=RXManualControlTimerPeriod);	
						//carts are not aligned, so they need to be arranged first
						ELSE
							GVL.Manual_Align_Command:=TRUE; //the main logic will set it to false when is done
							GVL.Manual_Set_Angle_Front_SetPoint:=0;
							GVL.Manual_Set_Angle_Back_SetPoint:=0;
							DATA_TX[0]:=CAN_ID_CommandArc;  //agribot ID 
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandArc, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);		
							//CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandAlign, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);							
						END_IF						
				ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandSetRPM THEN
					IF DATA_RX[0]<=100 THEN
						GVL.RPMUserRequest:=DATA_RX[0];
					ELSE 
						GVL.RPMUserRequest:=255;
					END_IF
					DATA_TX[0]:=CAN_ID_CommandSetRPM;
					CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandSetRPM , xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);							

				//=======================================================================================================
				//align one cart to another cart
				ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandAlignCartToCart THEN
					IF GVL.Manual_IS_BUSY THEN
						DATA_TX[0]:=CAN_ID_CommandAlignCartToCart;  //send error code BUSY
						DATA_TX[1]:=16#0F;
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
					ELSE
						IF DATA_RX[0]=1 THEN
							GVL.Manual_Set_Front_Command:=TRUE;
							GVL.Manual_Set_Angle_Front_SetPoint:=GVL.Back_Cart_Rotation;
						ELSE
							GVL.Manual_Set_Back_Command:=TRUE;
							GVL.Manual_Set_Angle_Back_SetPoint:=GVL.Front_Cart_Rotation;
						END_IF
						DATA_TX[0]:=CAN_ID_CommandAlignCartToCart;
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandAlignCartToCart, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);							
					END_IF
				//=======================================================================================================
				//set switch 
				ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandSetSwitch THEN
					IF DATA_RX[0]=0 THEN
						IF DATA_RX[2]<=100 THEN
							IF DATA_RX[1]=0 THEN
								iterator:=1; 
								//set all to off state
								WHILE iterator<12 DO
									GVL.SwitchState[iterator]:=FALSE;
									//set level
									GVL.SwitchSetLevel[iterator]:=DATA_RX[2];
									iterator:=iterator+1;
								END_WHILE
							ELSE
								iterator:=1; 
								//set all to on state
								WHILE iterator<12 DO
									GVL.SwitchState[iterator]:=TRUE;
									//set level
									GVL.SwitchSetLevel[iterator]:=DATA_RX[2];
									iterator:=iterator+1;
								END_WHILE
							END_IF
							DATA_TX[0]:=CAN_ID_CommandSetSwitch;
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandSetSwitch, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);							
						ELSE
							//error
							iterator:=1; 
							//set all to off state
							WHILE iterator<12 DO
									GVL.SwitchState[iterator]:=FALSE;
									//set level
									//GVL.SwitchSetLevel[iterator]:=DATA_RX[2];
									iterator:=iterator+1;
							END_WHILE
							DATA_TX[0]:=CAN_ID_CommandSetSwitch;  //send error code 
							DATA_TX[1]:=16#03; //send error wrong command data
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
						END_IF
					ELSE
						//if there is a switch with such a number
						IF DATA_RX[0]<=12 THEN
							//check if set level is beyond the range
							IF DATA_RX[2]<=100 THEN
								IF DATA_RX[1]=0 THEN
									GVL.SwitchState[DATA_RX[0]]:=FALSE;
								ELSE
									GVL.SwitchState[DATA_RX[0]]:=TRUE;
								END_IF
								GVL.SwitchSetLevel[DATA_RX[0]]:=DATA_RX[2];	
								DATA_TX[0]:=CAN_ID_CommandSetSwitch;
								CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_CommandSetSwitch, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);							
							ELSE
								GVL.SwitchState[DATA_RX[0]]:=FALSE;
								DATA_TX[0]:=CAN_ID_CommandSetSwitch;  //send error code
								DATA_TX[1]:=16#03; //send error wrong command data
								CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
							END_IF	
						ELSE
							DATA_TX[0]:=CAN_ID_CommandSetSwitch;  //send error code 
							DATA_TX[1]:=16#03; //send error wrong command data
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXManualError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
						END_IF	
					END_IF
				ELSIF CANwirelessRXblock.udiID=CAN_ID_CommandStartEngine THEN
					IF NOT RXStopTimer.Q THEN
						IF GVL.EnginesReady=FALSE OR GVL.EnginesWasON=FALSE THEN		
							GVL.ManualStartEngineRequest:=TRUE;
							GVL.ManualStopEngineRequest:=FALSE;
						ELSE
							GVL.ManualStopEngineRequest:=TRUE;
							GVL.ManualStartEngineRequest:=FALSE;
						END_IF
						//RXStopTimer(in:=FALSE, PT:=T#1S);
					END_IF	
				END_IF
			END_IF
		//=======================================================================================================
		//if received a hearbeat, then reset the timer, if wrong number send error
			IF CANwirelessRXblock.udiID=CAN_ID_Heartbeat THEN
				IF hearbeat_counter=255 THEN
					IF DATA_RX[0]=0 THEN		//if the last hearbeat has been missed
						hearbeat_counter:=DATA_RX[0];    	//save the latest hearbeat
						RXHeartbeatTimer(IN:=FALSE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer
						RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer
						DATA_TX[0]:=hearbeat_counter;  		//latest hearbeat 
						//send your own hearbeat
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_Heartbeat, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);	
					END_IF
				ELSE
					IF DATA_RX[0]-hearbeat_counter=1 THEN 	//check if any hearbeat was missed
						hearbeat_counter:=DATA_RX[0];    	//save the latest hearbeat
						RXHeartbeatTimer(IN:=FALSE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer
						RXHeartbeatTimer(IN:=TRUE, PT:=RXHeartbeatTimerPeriod); 		//reset heartbeat timer
						DATA_TX[0]:=hearbeat_counter;  		//latest hearbeat 
						//send your own hearbeat
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_Heartbeat, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);	
					ELSE 
						debugHeart:=DATA_RX[0]-hearbeat_counter;
						DATA_TX[0]:=16#00;		
						DATA_TX[1]:=16#0F;
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	
					END_IF
				END_IF
		//=======================================================================================================
		//if received data request, send data
			ELSIF  CANwirelessRXblock.udiID = en_canFrameID.CAN_ID_AgribotStatus1 THEN //instead of data_request ID, also == 100
					IF CANwirelessTXblock.xError=FALSE THEN //i wszystko ok z TX
						//engine data 1
						tempdata:=REAL_TO_UINT(Engine_Speed);
						dataPointer:=ADR(tempdata);
						DATA_TX[0]:=dataPointer^[2];//[2]						//uint, predkosc obrotowa w RPM
						DATA_TX[1]:=dataPointer^[1];//[1]						//
						DATA_TX[2]:=INT_TO_USINT(Actual_Engine_Percent_Torque); //integer, torque in percents of max torque
						DATA_TX[3]:=REAL_TO_USINT(Engine_Fuel_Rate*10);  			//engine fuel rate
						DATA_TX[4]:=GVL.FuelLevel;									//fuel level
						DATA_TX[5]:=FuelTemperature;							//engine fuel temperature
						DATA_TX[6]:=16#FF;										//unused
						DATA_TX[7]:=16#FF;										//
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_AgribotStatus1, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send data 1
						licznik_data:=licznik_data+1;
						IF CANwirelessTXblock.xError=FALSE THEN
							//engine data 2
							tempdata:=REAL_TO_UDINT(Engine_Total_Hours_of_Operation*10); //losing the 1/10 resolution, MTH
							dataPointer:=ADR(tempdata);
							DATA_TX[0]:=dataPointer^[4]; 
							DATA_TX[1]:=dataPointer^[3];
							DATA_TX[2]:=dataPointer^[2]; 
							DATA_TX[3]:=dataPointer^[1];							
							tempdata:=REAL_TO_UDINT(Engine_Total_Fuel_Used*10);	//multiplied by 10 to not lose the data
							dataPointer:=ADR(tempdata);		
							DATA_TX[4]:=dataPointer^[4];  //paliwo pochloniete przez caly czas pracy
							DATA_TX[5]:=dataPointer^[3];
							DATA_TX[6]:=dataPointer^[2];
							DATA_TX[7]:=dataPointer^[1];
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_AgribotStatus2, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send data 2

							DATA_TX[0]:=16#FF;  	//agribots velocity
							DATA_TX[1]:=REAL_TO_USINT((FuelLevelLitres/Engine_Fuel_Rate));		//predicted work time with remaing fuel
							DATA_TX[2]:=REAL_TO_USINT(GVL.OilTemperature+80);	//oil temperature
							tempdata:=REAL_TO_UINT(GVL.OilPressure);
							dataPointer:=ADR(tempdata);
							DATA_TX[3]:=dataPointer^[2];	//
							DATA_TX[4]:=dataPointer^[1];	//
							GPSaccurracynote:=0;
							//if gps fixed send a note of how effective it is now
							IF GVL.GPSFix=3 THEN
								GPSaccurracynote:=(100.0/UDINT_TO_REAL(GVL.GPSAccuracyHorizontal))*30+(100.0/UDINT_TO_REAL(GVL.GPSAccuracyVertical))*30;
								IF GPSaccurracynote>255 THEN
									GPSaccurracynote:=255;
								END_IF
								DATA_TX[5]:=REAL_TO_BYTE(GPSaccurracynote);
							ELSE
								DATA_TX[5]:=REAL_TO_BYTE(GPSaccurracynote);	//
							END_IF							
							DATA_TX[6]:=16#FF;	//
							DATA_TX[7]:=16#FF;	//

							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_AgribotStatus3, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send data 3
							tempdata:=REAL_TO_INT(GVL.Front_Cart_Rotation*10);
							dataPointer:=ADR(tempdata);
							DATA_TX[0]:=dataPointer^[2];  	//Cart 1 rotation
							DATA_TX[1]:=dataPointer^[1];	
							tempdata:=REAL_TO_INT(GVL.Back_Cart_Rotation*10);
							dataPointer:=ADR(tempdata);
							DATA_TX[2]:=dataPointer^[2];		//Cart 2 rotation
							DATA_TX[3]:=dataPointer^[1];		//
							tempdata:=REAL_TO_INT(Angle_Roll*10);
							dataPointer:=ADR(tempdata);
							DATA_TX[4]:=dataPointer^[2];		//Agribots X inclination
							DATA_TX[5]:=dataPointer^[1];		//
							tempdata:=REAL_TO_INT(Angle_Pitch*10);
							dataPointer:=ADR(tempdata);
							DATA_TX[6]:=dataPointer^[2];		//Agribots Y inclination
							DATA_TX[7]:=dataPointer^[1];		//
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_AgribotStatus4, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send data 4

							//weather data not yet available
							tempdata:=REAL_TO_DINT(WindSpeed);
							dataPointer:=ADR(tempdata);
							DATA_TX[0]:=dataPointer^[4];  	
							DATA_TX[1]:=dataPointer^[3];		
							DATA_TX[2]:=dataPointer^[2];		
							DATA_TX[3]:=dataPointer^[1];		
							//weather data not yet available
							tempdata:=REAL_TO_DINT(WindDirection);
							dataPointer:=ADR(tempdata);
							DATA_TX[4]:=dataPointer^[4];	
							DATA_TX[5]:=dataPointer^[3];		
							DATA_TX[6]:=dataPointer^[2];		
							DATA_TX[7]:=dataPointer^[1];		
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_AgribotStatus5, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send data 5

							//weather data not yet available
							tempdata:=REAL_TO_INT(Temperature);
							dataPointer:=ADR(tempdata);
							DATA_TX[0]:=dataPointer^[2]; 	
							DATA_TX[1]:=dataPointer^[1];
							tempdata:=REAL_TO_INT(Humidity);
							dataPointer:=ADR(tempdata);		
							DATA_TX[2]:=dataPointer^[2];		
							DATA_TX[3]:=dataPointer^[1];
							tempdata:=REAL_TO_INT(_AtmPressure);
							dataPointer:=ADR(tempdata);	
							DATA_TX[4]:=dataPointer^[2];		
							DATA_TX[5]:=dataPointer^[1];		
							DATA_TX[6]:=16#50;		
							DATA_TX[7]:=16#60;		
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_AgribotStatus6, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send data 5

							tempdata:=REAL_TO_DINT(GVL.Latitude*1000000);
							dataPointer:=ADR(tempdata);
							DATA_TX[0]:=dataPointer^[4]; 	
							DATA_TX[1]:=dataPointer^[3];
							DATA_TX[2]:=dataPointer^[2]; 	
							DATA_TX[3]:=dataPointer^[1];
							tempdata:=REAL_TO_DINT(GVL.Longitude*1000000);
							DATA_TX[4]:=dataPointer^[4]; 	
							DATA_TX[5]:=dataPointer^[3];
							DATA_TX[6]:=dataPointer^[2]; 	
							DATA_TX[7]:=dataPointer^[1];

							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_AgribotStatus7, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send data 5


							IF CANwirelessTXblock.xError=TRUE THEN
								status:=0; //can bus doesnt work
								EXIT; //stop reading the buffer, no connection
							END_IF
						ELSE
							status:=0; //can bus doesnt work
							EXIT; //stop reading the buffer, no connection
						END_IF	
					ELSE
						status:=0; //can bus doesnt work
						EXIT; //stop reading the buffer, no connection
					END_IF
		//=======================================================================================================
		//if received get switches info
			ELSIF CANwirelessRXblock.udiID=CAN_ID_GetSwitchStatus THEN
				IF CANwirelessTXblock.xError=FALSE THEN
					IF DATA_RX[0]=255 THEN
						iterator:=1;
						WHILE iterator<12 DO
							DATA_TX[0]:=iterator; //switch number 
							IF GVL.SwitchState[iterator] THEN //switch state
								DATA_TX[1]:=1;
							ELSE
								DATA_TX[1]:=0;
							END_IF
							DATA_TX[2]:=0;  //if only from 0 to 100 percent, then the first data byte is useless 
							DATA_TX[3]:=GVL.SwitchCurrentLevel[iterator];							

							DATA_TX[4]:=iterator+1; //next switch number 
							IF GVL.SwitchState[iterator+1] THEN //switch state
								DATA_TX[5]:=1;
							ELSE
								DATA_TX[5]:=0;
							END_IF
							DATA_TX[6]:=0;  //if only from 0 to 100 percent, then the first data byte is useless 
							DATA_TX[7]:=GVL.SwitchCurrentLevel[iterator+1];	

							//send complete frame of 8 bytes
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_GetSwitchStatus, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send switch data
							//check if there is and error
							IF CANwirelessTXblock.xError=TRUE THEN 
								status:=0; //can bus doesnt work
								EXIT; //stop sending of data, no connection
							END_IF
							iterator:=iterator+2; //send the next pair of switches
						END_WHILE
					//send the wanted switch data
					ELSE
						IF DATA_RX[0]<=12 THEN //czy istnieje takis switch
							DATA_TX[0]:=DATA_RX[0]; //switch number 
							IF GVL.SwitchState[DATA_RX[0]] THEN //switch state
								DATA_TX[1]:=1;
							ELSE
								DATA_TX[1]:=0;
							END_IF
							DATA_TX[2]:=0;  //if only from 0 to 100 percent, then the first data byte is useless 
							DATA_TX[3]:=GVL.SwitchCurrentLevel[DATA_RX[0]];
							DATA_TX[4]:=16#FF;
							DATA_TX[5]:=16#FF;
							DATA_TX[6]:=16#FF;
							DATA_TX[7]:=16#FF;
							//send the frame with switch data
							CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_GetSwitchStatus, xExtended:=FALSE, usiDLC:=8,aData:=DATA_TX, xEnable:=TRUE);	//send switch data
							//check if there is and error
							IF CANwirelessTXblock.xError=TRUE THEN 
								status:=0; //can bus doesnt work
								EXIT; //stop reading the buffer, no connection
							END_IF
						END_IF
					END_IF
				ELSE
					status:=0; //can bus doesnt work
					EXIT; //stop reading the buffer, no connection
				END_IF
		//=======================================================================================================
		//if received enginge error request
			ELSIF CANwirelessRXblock.udiID=CAN_ID_GetEngineError THEN 
				IF CANwirelessTXblock.xError=FALSE THEN
					//lamp state frame
					DATA_TX[0]:=SHR((GVL.DiagLampState AND 2#11000000), 6); //MIL
					DATA_TX[1]:=SHR((GVL.DiagLampState AND 2#00110000), 4);	//RSL
					DATA_TX[2]:=SHR((GVL.DiagLampState AND 2#00001100), 2); //AWL
					DATA_TX[3]:=GVL.DiagLampState AND 2#00000011;			//PL
					DATA_TX[4]:=GVL.iloscDTC;
					CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_GetEngineError, xExtended:=FALSE, usiDLC:=5,aData:=DATA_TX, xEnable:=TRUE);//send DM1 data
					//error codes frames
					iterator:=0;
					WHILE iterator<GVL.iloscDTC DO
						//SPN
						tempdata:=DWORD_TO_UDINT(GVL.SPNlistV1[iterator].dwSPN); 
						dataPointer:=ADR(tempdata);
						DATA_TX[0]:=dataPointer^[3];
						DATA_TX[1]:=dataPointer^[2];
						DATA_TX[2]:=dataPointer^[1];
						//FMI
						DATA_TX[3]:=GVL.SPNlistV1[iterator].eFMI;
						//OCC
						DATA_TX[4]:=GVL.SPNlistV1[iterator].byOC;
						//STAT
						IF GVL.SPNlistV1[iterator].byOC<127 THEN
							//is active or no more active if occ dont rise, so this error is no more a problem
							DATA_TX[5]:=1;
						ELSE
							//have gone into passive state, error is still a problem
							DATA_TX[5]:=0;
						END_IF
						DATA_TX[6]:=iterator;
						CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_GetEngineError, xExtended:=FALSE, usiDLC:=7,aData:=DATA_TX, xEnable:=TRUE);//send DM1 data
						iterator:=iterator+1;
					END_WHILE
				ELSE
					status:=0; //can bus doesnt work
					EXIT; //stop reading the buffer, no connection
				END_IF		
		//=======================================================================================================
		//if received manual control initialization
			ELSIF CANwirelessRXblock.udiID=CAN_ID_ManualControlInit THEN 
				GVL.ManualControlDemand:=TRUE;  //flag for the main logic to get ready for manual control
				ManualNotConfirmed:=TRUE;
				//confirm that you got the order
				DATA_TX[0]:=16#FF;  //dummy byte
				CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_ManualControlInit, xExtended:=FALSE, usiDLC:=1,aData:=DATA_TX, xEnable:=TRUE);	//send data 2
		//=======================================================================================================
		//if received manual control confirmation from the device, check if it was planned
			ELSIF CANwirelessRXblock.udiID=CAN_ID_ManualOK THEN
				IF (GVL.ManualControlState=2) AND NOT ManualNotConfirmed THEN //check if agribot is ready and waiting
					GVL.ManualControlState:=3;	//received the manual control confirmation, manual control is active from that moment
					status:=3;				//activate reading of move commands
				ELSE					//send error that agribot isnt ready or was not waiting at all
					DATA_TX[0]:=16#00;  //error code
					DATA_TX[1]:=16#01;  //agribot not ready
					CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);	//send error
				END_IF
			END_IF

		//=======================================================================================================
		//=======================================================================================================			
		//=======================================================================================================
		//GPS
		IF CANwirelessRXblock.udiID = 16#1C0 THEN 
			GyroX:= 0;
			GyroX:= SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]); 
			GyroXdeg:= (GyroX/1000.0)*57.29;
			GyroY:= 0;
			GyroY:= SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]); 
			GyroYdeg:= (GyroY/1000.0)*57.29;
		END_IF;

		IF CANwirelessRXblock.udiID = 16#2C0 THEN 
			GyroZ:= 0;
			GyroZ:= SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]); 
			GyroZdeg:= (GyroZ/1000.0)*57.29;
			AaccelX:= 0;
			AaccelX:= SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]); 
			AaccelXdeg:= (AaccelX/1000.0);
		END_IF;

		IF CANwirelessRXblock.udiID = 16#3C0 THEN 
			AaccelY:= 0;
			AaccelY:= SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]); 
			AaccelYdeg:= (AaccelY/1000.0);
			AaccelZ:= 0;
			AaccelZ:= SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]); 
			AaccelZdeg:= (AaccelZ/1000.0);
		END_IF;

		IF CANwirelessRXblock.udiID = 16#4C0 THEN 
			MagnX :=  SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]);

			MagnY :=  SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]);
		END_IF;

		IF CANwirelessRXblock.udiID = 16#5C0 THEN 
			MagnZ :=  SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]);

			Roll :=  SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]);
			RollDeg:= (Roll/1000.0)*57;
		END_IF;

		IF CANwirelessRXblock.udiID = 16#6C0 THEN 
			Pitch :=  SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]);
			PitchDeg:= (Pitch/1000.0)*57;

			Yaw :=  SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]);
			YawDeg:= (Yaw/1000.0)*57;
		END_IF;

		IF CANwirelessRXblock.udiID = 16#18A THEN 
			GVL.Latitude :=  (SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]))/10000000.0;

			GVL.Longitude :=  (SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]))/10000000.0;

			//czy GPS zlapal fixa
			(*
			IF GVL.GPSFix=3 THEN
				//czy zmiana jest wystarczająco duża
				getDistance(startLAT:=GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LAT, startLON:=GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LON,
					endLAT:=GVL.Latitude, endLON:=GVL.Longitude);

				IF getDistance.dist_m >minimalDistance THEN
				//IF ((ABS(GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LAT-GVL.Latitude)>0.00001) OR (ABS(GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LON-GVL.Longitude)>0.00001)) THEN
					GVL.GPS_Last_Positions_Index:=GVL.GPS_Last_Positions_Index+1;
					IF (GVL.GPS_Last_Positions_Index>10) THEN
						GVL.GPS_Last_Positions_Index:=0;
					END_IF
					GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LAT:=GVL.Latitude;
					GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LON:=GVL.Longitude;
					GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].AccHorizontal:=GVL.GPSAccuracyHorizontal;
					GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].AccVertical:=GVL.GPSAccuracyVertical;
					IF GVL.GPS_Last_Positions_Index=0 THEN
						indexdummy:=10;
					ELSE
						indexdummy:=GVL.GPS_Last_Positions_Index-1;
					END_IF

					IF (GVL.GPS_Last_Positions[indexdummy].LAT<>0 OR GVL.GPS_Last_Positions[indexdummy].LON<>0) THEN
						getBearing(startLAT:=GVL.GPS_Last_Positions[indexdummy].LAT, 
									startLON:=GVL.GPS_Last_Positions[indexdummy].LON,
									endLAT:=GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LAT, 
									endLON:=GVL.GPS_Last_Positions[GVL.GPS_Last_Positions_Index].LON );
						GVL.GPS_Heading_History[GVL.GPS_Last_Positions_Index].bearing:=getBearing.bearing;
						//estimate accuracy 10 cm is counted as acceptable level of accuracy, the smaller the note better the accuracy
						GVL.GPS_Heading_History[GVL.GPS_Last_Positions_Index].AccNote:=GVL.GPSAccuracyHorizontal/100+GVL.GPSAccuracyVertical/100;
					END_IF
				END_IF

			END_IF
			*)
		END_IF

		IF CANwirelessRXblock.udiID = 16#28A THEN 
			GVL.GPSFix :=DATA_RX[4];
		END_IF;

		IF CANwirelessRXblock.udiID = 16#38A THEN
			GVL.GPSAccuracyHorizontal :=(SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]));
			GVL.GPSAccuracyVertical :=(SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]));
		END_IF

		IF CANwirelessRXblock.udiID = 16#48A THEN
			GPSMomentaryHeading :=  (SHL(USINT_TO_DINT(DATA_RX[3]), 24) OR SHL(USINT_TO_DINT(DATA_RX[2]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[1]), 8)  OR USINT_TO_DINT(DATA_RX[0]))/100000.0;

			GVL.GPSHeadingAccuracy := (SHL(USINT_TO_DINT(DATA_RX[7]), 24) OR SHL(USINT_TO_DINT(DATA_RX[6]), 16) OR 
					  SHL(USINT_TO_DINT(DATA_RX[5]), 8)  OR USINT_TO_DINT(DATA_RX[4]))/100000.0;

			IF GVL.GPSHeadingAccuracy <=10 THEN
				GVL.GPSHeadingFilterData[GVL.GPSHeadingFilterDataIndex].bearing:=GPSMomentaryHeading ;
				GVL.GPSHeadingFilterData[GVL.GPSHeadingFilterDataIndex].Acc:=GVL.GPSHeadingAccuracy;
				headingFilter();				
				headingFilter.output_mean;
				GVL.GPSHeading:=headingFilter.output_median;			
				GVL.GPSHeadingFilterDataIndex:=GVL.GPSHeadingFilterDataIndex+1;
				GVL.GPSHeadingFilterDataIndex:=GVL.GPSHeadingFilterDataIndex MOD 10;

			END_IF

		END_IF

		//=======================================================================================================
		//Check hearbeat
		//=======================================================================================================
			IF RXHeartbeatTimer.Q THEN //if heartbeat was absent for 200ms, then disconnect
				status:=1;			//back to waiting state
				GVL.DeviceConnected:=FALSE; //no connection flag
				GVL.ManualControlState:=0; //no manual control flag
				GVL.TargetReached:=TRUE;
				GVL.ComCart1Rot:=FALSE;
				GVL.ComCart2Rot:=FALSE;
				GVL.ComCart1RotDir:=FALSE;
				GVL.ComCart2RotDir:=FALSE;
				GVL.ComCartsStraight:=FALSE;
				GVL.ComCart1RotDir:=FALSE;
				GVL.ManualStartEngineRequest:=FALSE;
				GVL.Manual_Arc_Continue:=FALSE;
				GVL.Manual_Arc_Radius:=0;
				GVL.RPMUserRequest:=255; //engine is free
				//turn off switches
				Switch_iterator:=1;
				WHILE Switch_iterator<=12 DO
					GVL.SwitchState[Switch_iterator]:=FALSE;
					GVL.SwitchSetLevel[Switch_iterator]:=0;
					Switch_iterator:=Switch_iterator+1;
				END_WHILE

				//send error message, connection lost, reason: lack of heartbeat, connection is unstable 
				DATA_TX[0]:=16#00;		
				DATA_TX[1]:=16#0F;
				CANwirelessTXblock(eChannel:=ifmDevice.CHAN_3, udiID:=CAN_ID_TXError, xExtended:=FALSE, usiDLC:=2,aData:=DATA_TX, xEnable:=TRUE);
				EXIT; //stop reading the buffer, no connection
			ELSE
//=======================================================================================================
				//if everything is ok take the next message
				//take next message from the buffer
//=======================================================================================================	
				CANwirelessRXblock(udiIDstart:=16#00, udiIDstop:=16#7FF, eChannel:=ifmDevice.CHAN_3, aData=>DATA_RX, xExtended:=FALSE, xEnable:=TRUE);
			END_IF			
		END_WHILE
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	
	END_IF	
END_IF

IF ((y/x)<0.005) THEN
	IF x>0 THEN
		output:=y/x;
	ELSIF (x<0 AND y>=0) THEN
		output:=y/x+PI;
	ELSIF (x<0 AND y<0) THEN
		output:=y/x-PI;
	ELSIF (x=0 AND y>0) THEN
		output:=PI/2;
	ELSIF (x=0 AND y<0) THEN
		output:=-PI/2;
	END_IF
ELSE	
	IF x>0 THEN
		output:=ATAN(y/x);
	ELSIF (x<0 AND y>=0) THEN
		output:=ATAN(y/x)+PI;
	ELSIF (x<0 AND y<0) THEN
		output:=ATAN(y/x)-PI;
	ELSIF (x=0 AND y>0) THEN
		output:=PI/2;
	ELSIF (x=0 AND y<0) THEN
		output:=-PI/2;
	END_IF
END_IF

startLONRadians:=startLON*deegresTORadians;
startLATRadians:=startLAT*deegresTORadians;
endLONRadians:=endLON*deegresTORadians;
endLATRadians:=endLAT*deegresTORadians;

dLON:=endLONRadians-startLONRadians;
dPHI := LN(TAN(endLATRadians/2.0+PI/4.0)/TAN(startLATRadians/2.0+PI/4.0));

//jesli równe/mniejsze niz 0.1 stopni to przyjmij rowne ktowi w radianach
IF dLON<=0.00174532925 THEN
	deltaLONcos:=1-(dLON*dLON)/2;
	deltaLONsin:=dLON;
ELSE
	deltaLONcos:=COS(dLON);
	deltaLONsin:=SIN(dlon);
END_IF

IF startLATRadians<=0.00174532925 THEN
	startLATsin:=startLATRadians;
	startLATcos:=1-(startLATRadians*startLATRadians)/2;
ELSE
	startLATsin:=SIN(startLATRadians);
	startLATcos:=COS(startLATRadians);
END_IF

IF endLATRadians <= 0.00174532925 THEN
	endLATsin:=endLATRadians;
	endLATcos:=1-(endLATRadians*endLATRadians)/2;
ELSE
	endLATsin:=SIN(endLATRadians);
	endLATcos:=COS(endLATRadians);
END_IF


(*
IF (ABS(dLON) > PI) THEN
	IF (dLON > 0.0) THEN
       dLON := -(2.0 * PI - dLON);
    else
       dLON := (2.0 * PI + dLON);
	END_IF
END_IF
atan2(x:=dPHI, y:=dLON);
fmod(x:=(radiansTODegrees*(atan2.output)+360.0), y:= 360.0);
*)
atan2(x:=(startLATcos*endLATsin-startLATsin*endLATcos*deltaLONcos), y:=(deltaLONsin*endLATcos));
fmod(x:=(radiansTODegrees*(atan2.output)+360.0), y:= 360.0);
bearing:= fmod.output;

//atan(

latMid := (startLAT+endLAT )/2.0;  // 


m_per_deg_lat := 111132.954 - 559.822 * COS( 2.0 * latMid ) + 1.175 * COS( 4.0 * latMid);
m_per_deg_lon := (3.14159265359/180 ) * 6367449 * COS ( latMid );

deltaLat := ABS(startLAT - endLAT);
deltaLon := ABS(startLON - endLON);

dist_m := SQRT ( (deltaLat * m_per_deg_lat)*(deltaLat * m_per_deg_lat) + ( deltaLon * m_per_deg_lon)*( deltaLon * m_per_deg_lon) );

i:=0;
j:=0;

//przepisz tablice dla medianowego 
FOR i:=0 TO 10 BY 1 DO
	temp_array_med[i]:=GVL.GPSHeadingFilterData[i].bearing;
END_FOR
i:=0;
FOR j:=0 TO 10 BY 1 DO
	FOR i:=0 TO 9 BY 1 DO
		IF temp_array_med[i]>temp_array_med[i+1] THEN
			temp:=temp_array_med[i+1];
			temp_array_med[i+1]:=temp_array_med[i];
			temp_array_med[i]:=temp;
		END_IF
	END_FOR
END_FOR

//czy między maksymalną wartoscią a minimalną jest przejście przez 0
IF (temp_array_med[0]<=90 AND temp_array_med[10]>=270) THEN
	//przesuń wartości z pierwszej ćwiartki o 360 stopni
	FOR i:=0 TO 10 BY 1 DO
		IF temp_array_med[i]<=90 THEN
				temp_array_mean[i]:=temp_array_med[i]:=temp_array_med[i]+360;
		END_IF
	END_FOR

	FOR j:=0 TO 10 BY 1 DO
		FOR i:=0 TO 9 BY 1 DO
			IF temp_array_med[i]>temp_array_med[i+1] THEN
				temp:=temp_array_med[i+1];
				temp_array_med[i+1]:=temp_array_med[i];
				temp_array_med[i]:=temp;
			END_IF
		END_FOR
	END_FOR

	output_median:=temp_array_med[5];
	//jesli w pierwszej ćwiartce to wroc do niej
	IF output_median>=360 THEN
		output_median:=output_median-360;
	END_IF

	FOR i:=0 TO 10 BY 1 DO
		temp:=temp+temp_array_mean[i]*(1/GVL.GPSHeadingFilterData[i].acc);
		temp2:=temp2+(1/GVL.GPSHeadingFilterData[i].acc);
	END_FOR

	IF temp2<>0 THEN
		output_mean:=temp/temp2;
		IF output_mean>=360 THEN
			output_mean:=output_mean-360;
		END_IF
	ELSE
		output_mean:=0;
	END_IF

	//powtórz sortowanie dla nowych wartości
//jesli nie to normalnie
ELSE 
	output_median:=temp_array_med[5];

	temp:=0;
	temp2:=0;
	i:=0;
	FOR i:=0 TO 10 BY 1 DO
		temp:=temp+GVL.GPSHeadingFilterData[i].bearing*(1/GVL.GPSHeadingFilterData[i].acc);
		temp2:=temp2+(1/GVL.GPSHeadingFilterData[i].acc);
	END_FOR

	IF temp2<>0 THEN
		output_mean:=temp/temp2;
	ELSE
		output_mean:=0;
	END_IF
	//output
END_IF

Create := lib500.IO_CAN_ConfigFIFO(ADR(hFIFO),
		FIFO_CAM_channel,
		20,
		FIFO_acceptable_frame_format,
		FIFO_frames_address,                                          
        FIFO_frames_mask);

		uiReadyFrames:=0;
IF Create=lib500_types.IO_ERRORTYPE.IO_E_OK THEN
	bisready:=TRUE;
END_IF

addFramesToFIFO := lib500.IO_CAN_ReadFIFO(hFIFO,
	ADR(can_frames),
	20,
	ADR(rec_data_size));

iCounter:=0;	
WHILE iCounter < rec_data_size DO
	arrFIFOBuffer[iBufferWriteIterator].udiCanID:=can_frames[iCounter].id;
	arrFIFOBuffer[iBufferWriteIterator].barrData:=can_frames[iCounter].data;
	iBufferWriteIterator:=iBufferWriteIterator+1;
	uiReadyFrames:=uiReadyFrames+1; // set the new amount of available frames for read
	iBufferWriteIterator:=iBufferWriteIterator MOD 64;
	iCounter:=iCounter+1;
END_WHILE

IF hFIFO<>0 AND uiReadyFrames >0 THEN
	getFirstFrame:=arrFIFOBuffer[iBufferReadIterator];    // get the oldest message
	iBufferReadIterator:=iBufferReadIterator+1; 		 // set iterator for next message
	uiReadyFrames:=uiReadyFrames-1;			    // set the new amount of available frames for read
	iBufferReadIterator:=iBufferReadIterator MOD 64;   // 
ELSE
	getFirstFrame.udiCanID:=0;
	getFirstFrame.barrData[0]:=0;
	getFirstFrame.barrData[1]:=0;
	getFirstFrame.barrData[2]:=0;
	getFirstFrame.barrData[3]:=0;
	getFirstFrame.barrData[4]:=0;
	getFirstFrame.barrData[5]:=0;
	getFirstFrame.barrData[6]:=0;
	getFirstFrame.barrData[7]:=0;
END_IF

//add messages to fifo if possible
IF GVL.BT_RXCanFramesFIFO.bReady=TRUE THEN
	GVL.BT_RXCanFramesFIFO.addFramesToFIFO();
END_IF
